SELECT 
    hostname as name, 
    count() as cnt
FROM syslog 
WHERE timestamp >= #{startTime} 
  AND timestamp <= #{endTime}
  AND hostname != ''
GROUP BY hostname
ORDER BY cnt DESC
LIMIT #{limit}

SELECT 
    appname as name, 
    count() as cnt
FROM syslog 
WHERE timestamp >= #{startTime} 
  AND timestamp <= #{endTime}
  AND appname != ''
GROUP BY appname
ORDER BY cnt DESC
LIMIT #{limit}

SELECT count() 
FROM syslog 
WHERE timestamp >= #{startTime} 
  AND timestamp <= #{endTime}
  AND severity IN ('ERROR', 'WARN', 'FATAL', 'CRITICAL', 'error', 'warn', 'fatal', 'critical', 'warning')

SELECT count() 
FROM syslog 
WHERE timestamp >= #{startTime} 
  AND timestamp <= #{endTime}

SELECT count(DISTINCT ${field}) 
FROM syslog 
WHERE timestamp >= #{startTime} 
  AND timestamp <= #{endTime}

SELECT 
    toStartOfMinute(timestamp) as minute,
    count() as cnt
FROM syslog 
WHERE timestamp >= #{startTime} 
  AND timestamp <= #{endTime}
GROUP BY minute
ORDER BY minute DESC
LIMIT #{limit}

SELECT count()
FROM syslog 
WHERE timestamp >= #{startTime} 
  AND timestamp <= #{endTime}
  AND severity IN ('ERROR', 'WARN', 'FATAL', 'CRITICAL')
